{"filePath":"/tmp/opencode/test-todo-app/src/todo.js","content":"/**
 * Simple in-memory Todo store with persistence via better-sqlite3
 */

let db = null;

export function initDb(dbPath = ':memory:') {
  try {
    const Database = require('better-sqlite3');
    db = new Database(dbPath);
    db.exec(`
      CREATE TABLE IF NOT EXISTS todos (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        completed INTEGER DEFAULT 0,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      )
    `);
    return true;
  } catch (err) {
    console.error('DB init error:', err.message);
    // Fallback to in-memory array
    db = null;
    return false;
  }
}

// In-memory fallback storage
let memTodos = [];
let memId = 1;

export function getStore() {
  if (db) return 'sqlite';
  return 'memory';
}

export function addTodo(title) {
  if (!title || title.trim().length === 0) {
    throw new Error('Title is required');
  }

  if (db) {
    const stmt = db.prepare('INSERT INTO todos (title) VALUES (?)');
    const result = stmt.run(title.trim());
    return { id: result.lastInsertRowid, title: title.trim(), completed: false };
  }

  const todo = { id: memId++, title: title.trim(), completed: false };
  memTodos.push(todo);
  return todo;
}

export function listTodos() {
  if (db) {
    const rows = db.prepare('SELECT * FROM todos ORDER BY created_at DESC').all();
    return rows.map(r => ({ ...r, completed: !!r.completed }));
  }
  return [...memTodos];
}

export function completeTodo(id) {
  if (db) {
    const result = db.prepare('UPDATE todos SET completed = 1 WHERE id = ?').run(id);
    return result.changes > 0;
  }
  const todo = memTodos.find(t => t.id === id);
  if (!todo) return false;
  todo.completed = true;
  return true;
}

export function deleteTodo(id) {
  if (db) {
    const result = db.prepare('DELETE FROM todos WHERE id = ?').run(id);
    return result.changes > 0;
  }
  const idx = memTodos.findIndex(t => t.id === id);
  if (idx === -1) return false;
  memTodos.splice(idx, 1);
  return true;
}

export function clearTodos() {
  if (db) {
    db.exec('DELETE FROM todos');
    return;
  }
  memTodos = [];
  memId = 1;
}
"}

{"filePath":"/tmp/opencode/test-todo-app/src/index.js","content":"/**
 * Todo App - Main entry point
 * HTTP server using Node.js built-in http module
 */
import { createServer } from 'node:http';
import { initDb, addTodo, listTodos, completeTodo, deleteTodo, getStore } from './todo.js';

const PORT = process.env.PORT || 3000;

// Initialize database
initDb();

const server = createServer((req, res) => {
  res.setHeader('Content-Type', 'application/json');
  const url = new URL(req.url, `http://${req.headers.host}`);
  const path = url.pathname;

  // CORS headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    res.end();
    return;
  }

  // Routes
  if (req.method === 'GET' && path === '/api/todos') {
    const todos = listTodos();
    res.writeHead(200);
    res.end(JSON.stringify({ todos, store: getStore() }));
    return;
  }

  if (req.method === 'POST' && path === '/api/todos') {
    let body = '';
    req.on('data', chunk => body += chunk);
    req.on('end', () => {
      try {
        const { title } = JSON.parse(body);
        const todo = addTodo(title);
        res.writeHead(201);
        res.end(JSON.stringify(todo));
      } catch (err) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: err.message }));
      }
    });
    return;
  }

  if (req.method === 'PUT' && path.startsWith('/api/todos/')) {
    const id = parseInt(path.split('/')[3]);
    const success = completeTodo(id);
    if (success) {
      res.writeHead(200);
      res.end(JSON.stringify({ success: true }));
    } else {
      res.writeHead(404);
      res.end(JSON.stringify({ error: 'Todo not found' }));
    }
    return;
  }

  if (req.method === 'DELETE' && path.startsWith('/api/todos/')) {
    const id = parseInt(path.split('/')[3]);
    const success = deleteTodo(id);
    if (success) {
      res.writeHead(200);
      res.end(JSON.stringify({ success: true }));
    } else {
      res.writeHead(404);
      res.end(JSON.stringify({ error: 'Todo not found' }));
    }
    return;
  }

  // Health check
  if (req.method === 'GET' && path === '/health') {
    res.writeHead(200);
    res.end(JSON.stringify({ status: 'ok', uptime: process.uptime() }));
    return;
  }

  // 404
  res.writeHead(404);
  res.end(JSON.stringify({ error: 'Not found' }));
});

server.listen(PORT, () => {
  console.log(`Todo server running on http://localhost:${PORT}`);
  console.log(`Store: ${getStore()}`);
});

export { server };
"}

{"filePath":"/tmp/opencode/test-todo-app/src/todo.test.js","content":"/**
 * Tests for Todo store
 */
import { describe, it, before, after } from 'node:test';
import assert from 'node:assert';
import { addTodo, listTodos, completeTodo, deleteTodo, clearTodos, initDb } from './todo.js';

describe('Todo Store', () => {
  before(() => {
    initDb();
    clearTodos();
  });

  after(() => {
    clearTodos();
  });

  it('should add a todo', () => {
    const todo = addTodo('Test task 1');
    assert.ok(todo.id > 0);
    assert.equal(todo.title, 'Test task 1');
    assert.equal(todo.completed, false);
  });

  it('should list todos', () => {
    addTodo('Test task 2');
    const todos = listTodos();
    assert.ok(todos.length >= 2);
  });

  it('should complete a todo', () => {
    const todo = addTodo('To complete');
    const result = completeTodo(todo.id);
    assert.equal(result, true);
    const todos = listTodos();
    const found = todos.find(t => t.id === todo.id);
    assert.equal(found.completed, true);
  });

  it('should delete a todo', () => {
    const todo = addTodo('To delete');
    const result = deleteTodo(todo.id);
    assert.equal(result, true);
    const todos = listTodos();
    const found = todos.find(t => t.id === todo.id);
    assert.equal(found, undefined);
  });

  it('should reject empty title', () => {
    assert.throws(() => addTodo(''), /Title is required/);
    assert.throws(() => addTodo('   '), /Title is required/);
  });

  it('should return false for non-existent todo completion', () => {
    const result = completeTodo(99999);
    assert.equal(result, false);
  });
