   * Lightweight keyword classifier — primary routing method.
   *
   * This runs FIRST on every route() call (O(n) keyword scan).
   * Results are returned directly when LLM is unavailable, or
   * used as a baseline when LLM refinement is available.
   *
   * Strategy:
   *   1. Score each category by how many of its keywords appear in input
   *   2. Pick the category with the highest score
   *   3. Calculate confidence as score / inputTokenCount (capped at 1.0)
   *   4. Default to "general" if no category scores > 0
   */
  private _keywordFallback(input: string): RouteMatch {
    const normalized = input.toLowerCase()

    // Score each category by how many keywords match
    let bestCat: RouteCategory | null = null
    let bestScore = 0
    let bestMatches: string[] = []

    for (const cat of this.categories) {
      if (cat.keywords.length === 0) continue
      let score = 0
      let matches: string[] = []
      for (const kw of cat.keywords) {
        if (normalized.includes(kw.toLowerCase())) {
          score++
          matches.push(kw)
        }
      }
      if (score > bestScore) {
        bestScore = score
        bestCat = cat
        bestMatches = matches
      }
    }

    const inputTokenCount = Math.max(2, normalized.split(/\s+/).length)
    const confidence = bestCat && bestScore > 0
      ? Math.min(1.0, bestScore / inputTokenCount)
      : 0.3

    const cat = bestCat && bestScore > 0 ? bestCat : this.categories.find(c => c.id === "general")

    return {
      input,
      intent: cat ? `Terkait ${cat.name}` : "Pengetahuan umum",
