/**
 * RouterAgent — keyword-first intent classifier with OpenCode SDK refinement.
 *
 * Strategy:
 *   1. Fast keyword matching (always runs first — O(n), deterministic)
 *   2. If OpenCode SDK is available, use it for LLM-based refinement
 *      (calls client.session.prompt() directly, NOT through plugin's LLMEngine wrapper)
 *   3. If SDK unavailable or LLM call fails, return keyword result silently
 *
 * No dependency on LLMEngine — calls OpenCode SDK directly.
 */
export class RouterAgent {
  private categories: RouteCategory[]
  private opencodeClient: unknown = null
  private pluginSessionId: string | null = null

  constructor(categories?: RouteCategory[]) {
    this.categories = categories ?? DEFAULT_CATEGORIES
  }

  setCategories(categories: RouteCategory[]): void {
    this.categories = categories
  }

  getCategories(): RouteCategory[] {
    return [...this.categories]
  }

  /** Set the OpenCode SDK client for direct LLM calls. Called once during plugin init. */
  setOpencodeClient(client: unknown): void {
    this.opencodeClient = client
  }

  /** Set session ID per-tool-call. Required for client.session.prompt(). */
  setSessionId(sessionId: string): void {
    this.pluginSessionId = sessionId
  }

  /** Check if OpenCode SDK is available for direct LLM calls. */
  private _sdkAvailable(): boolean {
    return this.opencodeClient !== null && this.pluginSessionId !== null
  }

  /**
   * Extract meaningful keywords from user input for RAG search.
   */
  private stopWords: Set<string> = new Set([
    "a", "an", "the", "is", "are", "was", "were", "be", "been", "being",
    "have", "has", "had", "do", "does", "did", "will", "would", "could",
    "should", "may", "might", "shall", "can", "need", "dare", "ought",
    "used", "to", "of", "in", "for", "on", "with", "at", "by", "from",
    "as", "into", "through", "during", "before", "after", "above", "below",
    "between", "out", "off", "over", "under", "again", "further", "then",
    "once", "here", "there", "when", "where", "why", "how", "all", "each",
    "every", "both", "few", "more", "most", "other", "some", "such", "no",
    "nor", "not", "only", "own", "same", "so", "than", "too", "very", "just",
    "because", "but", "and", "or", "if", "while", "although", "though",
    "what", "which", "who", "whom", "this", "that", "these", "those",
    "it", "its", "i", "me", "my", "we", "our", "you", "your", "he", "him",
    "his", "she", "her", "they", "them", "their",
    "dan", "di", "ke", "dari", "yang", "ini", "itu", "dengan", "untuk",
    "pada", "adalah", "telah", "sudah", "akan", "bisa", "dapat", "tidak",
    "ada", "juga", "atau", "saya", "kami", "kita", "mereka", "dia",
    "oleh", "sebagai", "tentang", "karena", "jika", "saat", "setelah",
    "sebelum", "antara", "tanpa", "sambil", "meski", "walaupun",
    "sangat", "agak", "cukup", "paling", "semua", "masing", "sendiri",
    "hal", "banyak", "sedikit", "lain", "baru", "lama", "besar", "kecil",
    "tolong", "mohon", "silakan", "terima", "kasih", "maaf",
  ])

  extractKeywords(input: string): { keywords: string[]; category: string } {
    const normalized = input.toLowerCase()
    const tokens = normalized.split(/[\s,.;:!?(){}[\]"'/\\@#$%^&*+=<>~`|]+/).filter(t => t.length > 2)

    const scored = new Map<string, number>()
    const matchedCategory = new Map<string, number>()

    for (const token of tokens) {
      if (this.stopWords.has(token)) continue
      if (/^\d+$/.test(token)) continue

      const currentScore = scored.get(token) ?? 0
      scored.set(token, currentScore + 1)

      for (const cat of this.categories) {
        if (cat.keywords.some(kw => kw.toLowerCase() === token)) {
          matchedCategory.set(cat.id, (matchedCategory.get(cat.id) ?? 0) + 2)
          scored.set(token, (scored.get(token) ?? 0) + 2)
        }
      }
    }

    const sorted = [...scored.entries()]
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([word]) => word)

    let bestCategory = "general"
    let bestScore = 0
    for (const [cat, score] of matchedCategory) {
      if (score > bestScore) {
        bestScore = score
        bestCategory = cat
      }
    }

    return { keywords: sorted, category: bestCategory }
  }

  /**
   * Pure keyword matching (synchronous, deterministic).
   */
  private _keywordMatch(input: string): RouteMatch {
    const normalized = input.toLowerCase()

    let bestCat: RouteCategory | null = null
    let bestScore = 0
    let bestMatches: string[] = []

    for (const cat of this.categories) {
      if (cat.keywords.length === 0) continue
      let score = 0
      let matches: string[] = []
      for (const kw of cat.keywords) {
        if (normalized.includes(kw.toLowerCase())) {
          score++
          matches.push(kw)
        }
      }
      if (score > bestScore) {
        bestScore = score
        bestCat = cat
        bestMatches = matches
      }
    }

    const inputTokenCount = Math.max(2, normalized.split(/\s+/).length)
    const confidence = bestCat && bestScore > 0
      ? Math.min(1.0, bestScore / inputTokenCount)
      : 0.3

    const cat = bestCat && bestScore > 0 ? bestCat : this.categories.find(c => c.id === "general")

    return {
      input,
      intent: cat ? `Terkait ${cat.name}` : "Pengetahuan umum",
      category: cat?.id ?? "general",
      confidence: parseFloat(confidence.toFixed(2)),
      usedLlm: false,
      suggestedTools: cat?.suggestedTools ?? [],
      suggestedRagIndex: cat?.suggestedRagIndex ?? "knowledge-general",
      reasoning: bestCat && bestScore > 0
        ? `Keyword match: "${bestMatches.slice(0, 5).join(", ")}"${bestMatches.length > 5 ? ` +${bestMatches.length - 5} more` : ""}`
        : "No keyword match, defaulting to general category",
    }
  }

  /**
   * Call OpenCode SDK directly for LLM-based intent refinement.
   * No caching, no fallback, no model resolution — raw SDK call.
   * Returns null if SDK is unavailable or call fails.
   */
  private async _callOpenCodeSDK(input: string): Promise<RouteMatch | null> {
    if (!this._sdkAvailable()) return null

    const client = this.opencodeClient as {
      session: {
        prompt: (opts: {
          body: { system?: string; noReply?: boolean; parts: Array<{ type: string; text: string }> }
          path: { id: string }
        }) => Promise<{ data?: { parts?: Array<{ type: string; text?: string }> }; parts?: Array<{ type: string; text?: string }> }>
      }
    }

    const categoryList = this.categories
      .filter(c => c.id !== "general")
      .map(c => `- "${c.id}": ${c.description}`)
      .join("\n")

    try {
      const timeoutMs = 30000
      const controller = new AbortController()
      const timeoutId = setTimeout(() => controller.abort(), timeoutMs)

      const result = await Promise.race([
        client.session.prompt({
          body: {
            system: `You are an intent classifier. Given user input, classify it into one of these categories:\n\n${categoryList}\n\n- "general": anything else\n\nReturn ONLY a JSON object with keys: category (string), confidence (0.0-1.0), reasoning (string). No other text.`,
            noReply: false,
            parts: [{ type: "text", text: `Classify this input: "${input}"` }],
          },
          path: { id: this.pluginSessionId! },
        }),
        new Promise<never>((_, reject) => {
          controller.signal.addEventListener("abort", () => {
            reject(new Error(`OpenCode SDK call timed out after ${timeoutMs}ms`))
          })
        }),
      ])
      clearTimeout(timeoutId)

      const parts = result.data?.parts ?? result.parts ?? []
      const textPart = parts.find((p: { type: string; text?: string }) => p.type === "text")
      const text = textPart?.text ?? ""
      if (!text.trim()) return null

      const jsonMatch = text.trim().match(/\{[\s\S]*\}/)
      if (!jsonMatch) return null

      const parsed = JSON.parse(jsonMatch[0])
      if (!parsed || parsed.status === "no_llm") return null

      const catId = parsed.category || ""
      const matchedCat = catId ? this.categories.find(c => c.id === catId) : null
      if (!matchedCat) return null

      const confidence = Math.min(1, Math.max(0, parsed.confidence ?? 0.5))
      return {
        input,
        intent: `Terkait ${matchedCat.name}`,
        category: catId,
        confidence: parseFloat(confidence.toFixed(2)),
        usedLlm: true,
        suggestedTools: matchedCat.suggestedTools ?? [],
        suggestedRagIndex: matchedCat.suggestedRagIndex ?? "knowledge-general",
        reasoning: parsed.reasoning ?? `OpenCode SDK classified as ${catId}`,
      }
    } catch {
      return null
    }
  }

  /**
   * Route input using keyword-first + OpenCode SDK refinement.
   *
   * Phase 1: Fast keyword matching (always runs first — synchronous, deterministic).
   * Phase 2: If OpenCode SDK is available, call client.session.prompt() directly
   *          for LLM-based category refinement.
   * Fallback: Pure keyword result (no scary errors, no wasted calls).
   */
  async route(input: string): Promise<RouteMatch> {
    const keywordResult = this._keywordMatch(input)

    if (this._sdkAvailable()) {
      const llmResult = await this._callOpenCodeSDK(input)
      if (llmResult) return llmResult
    }

    return keywordResult
  }
}

/**
 * Create a custom category for routing.
 */
export function createCategory(
  id: string,
  name: string,
  keywords: string[],
  description: string,
  tools?: string[],
): RouteCategory {
  return {
    id,
    name,
    keywords,
    description,
    suggestedTools: tools ?? [],
    suggestedRagIndex: `knowledge-${id}`,
  }
}
