{"filePath":"/tmp/opencode/test-agentic-full/src/db.js","content":"/**
 * Database connection manager
 * Singleton pattern untuk better-sqlite3
 */

import Database from 'better-sqlite3';

let db = null;

export function getDb(dbPath = ':memory:') {
  if (db) return db;
  db = new Database(dbPath);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  return db;
}

export function initDb(dbPath) {
  const database = getDb(dbPath);

  database.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      email TEXT UNIQUE NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);

  database.exec(`
    CREATE TABLE IF NOT EXISTS categories (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT UNIQUE NOT NULL,
      description TEXT DEFAULT '',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);

  database.exec(`
    CREATE TABLE IF NOT EXISTS todos (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      completed INTEGER DEFAULT 0,
      user_id INTEGER REFERENCES users(id),
      category_id INTEGER REFERENCES categories(id),
      priority INTEGER DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);

  return database;
}

export function closeDb() {
  if (db) {
    db.close();
    db = null;
  }
}

export function getStore() {
  return db ? 'sqlite' : 'none';
}
"}

{"filePath":"/tmp/opencode/test-agentic-full/src/todo.js","content":"/**
 * Todo CRUD operations
 */

import { getDb } from './db.js';

export function addTodo({ title, userId, categoryId, priority = 0 }) {
  if (!title || title.trim().length === 0) {
    throw new Error('Title is required');
  }

  const db = getDb();
  const stmt = db.prepare(
    'INSERT INTO todos (title, user_id, category_id, priority) VALUES (?, ?, ?, ?)'
  );
  const result = stmt.run(title.trim(), userId || null, categoryId || null, priority);

  return {
    id: result.lastInsertRowid,
    title: title.trim(),
    completed: false,
    userId: userId || null,
    categoryId: categoryId || null,
    priority,
  };
}

export function listTodos({ userId, categoryId, completed, search, sortBy = 'created_at', order = 'DESC' } = {}) {
  const db = getDb();
  let sql = 'SELECT * FROM todos WHERE 1=1';
  const params = [];

  if (userId !== undefined) {
    sql += ' AND user_id = ?';
    params.push(userId);
  }
  if (categoryId !== undefined) {
    sql += ' AND category_id = ?';
    params.push(categoryId);
  }
  if (completed !== undefined) {
    sql += ' AND completed = ?';
    params.push(completed ? 1 : 0);
  }
  if (search) {
    sql += ' AND title LIKE ?';
    params.push(`%${search}%`);
  }

  // Whitelist sorting to prevent injection
  const allowedSort = ['created_at', 'updated_at', 'priority', 'title'];
  const safeSort = allowedSort.includes(sortBy) ? sortBy : 'created_at';
  const safeOrder = order === 'ASC' ? 'ASC' : 'DESC';
  sql += ` ORDER BY ${safeSort} ${safeOrder}`;

  const rows = db.prepare(sql).all(...params);
  return rows.map(r => ({ ...r, completed: !!r.completed }));
}

export function getTodo(id) {
  const db = getDb();
  return db.prepare('SELECT * FROM todos WHERE id = ?').get(id);
}

export function updateTodo(id, { title, completed, categoryId, priority }) {
  const db = getDb();
  const sets = [];
  const params = [];

  if (title !== undefined) {
    sets.push('title = ?');
    params.push(title.trim());
  }
  if (completed !== undefined) {
    sets.push('completed = ?');
    params.push(completed ? 1 : 0);
  }
  if (categoryId !== undefined) {
    sets.push('category_id = ?');
    params.push(categoryId);
  }
  if (priority !== undefined) {
    sets.push('priority = ?');
    params.push(priority);
  }

  if (sets.length === 0) return false;

  sets.push('updated_at = CURRENT_TIMESTAMP');
  params.push(id);

  const result = db.prepare(`UPDATE todos SET ${sets.join(', ')} WHERE id = ?`).run(...params);
  return result.changes > 0;
}

export function completeTodo(id) {
  return updateTodo(id, { completed: true });
}

export function deleteTodo(id) {
  const db = getDb();
  const result = db.prepare('DELETE FROM todos WHERE id = ?').run(id);
  return result.changes > 0;
}

export function clearTodos() {
  const db = getDb();
  db.exec('DELETE FROM todos');
}
"}

