import { getDb } from './db.js';

export function createUser({ username, email }) {
  if (!username || username.trim().length === 0) {
    throw new Error('Username is required');
  }
  if (!email || !email.includes('@')) {
    throw new Error('Valid email is required');
  }

  const db = getDb();
  const stmt = db.prepare('INSERT INTO users (username, email) VALUES (?, ?)');

  try {
    const result = stmt.run(username.trim(), email.trim());
    return {
      id: result.lastInsertRowid,
      username: username.trim(),
      email: email.trim(),
    };
  } catch (err) {
    if (err.message.includes('UNIQUE')) {
      throw new Error('Username or email already exists');
    }
    throw err;
  }
}

export function listUsers() {
  const db = getDb();
  return db.prepare('SELECT * FROM users ORDER BY created_at DESC').all();
}

export function getUser(id) {
  const db = getDb();
  return db.prepare('SELECT * FROM users WHERE id = ?').get(id);
}

export function getUserByUsername(username) {
  const db = getDb();
  return db.prepare('SELECT * FROM users WHERE username = ?').get(username.trim());
}

export function deleteUser(id) {
  const db = getDb();
  const result = db.prepare('DELETE FROM users WHERE id = ?').run(id);
  return result.changes > 0;
}
"}

{"filePath":"/tmp/opencode/test-agentic-full/src/category.js","content":"/**
 * Category CRUD operations
 */

import { getDb } from './db.js';

export function createCategory({ name, description = '' }) {
  if (!name || name.trim().length === 0) {
    throw new Error('Category name is required');
  }

  const db = getDb();
  try {
    const result = db.prepare('INSERT INTO categories (name, description) VALUES (?, ?)')
      .run(name.trim(), description.trim());
    return {
      id: result.lastInsertRowid,
      name: name.trim(),
      description: description.trim(),
    };
  } catch (err) {
    if (err.message.includes('UNIQUE')) {
      throw new Error('Category already exists');
    }
    throw err;
  }
}

export function listCategories() {
  const db = getDb();
  return db.prepare('SELECT * FROM categories ORDER BY name ASC').all();
}

export function getCategory(id) {
  const db = getDb();
  return db.prepare('SELECT * FROM categories WHERE id = ?').get(id);
}

export function updateCategory(id, { name, description }) {
  const db = getDb();
  const sets = [];
  const params = [];

  if (name !== undefined) {
    sets.push('name = ?');
    params.push(name.trim());
  }
  if (description !== undefined) {
    sets.push('description = ?');
    params.push(description.trim());
  }

  if (sets.length === 0) return false;

  params.push(id);
  const result = db.prepare(`UPDATE categories SET ${sets.join(', ')} WHERE id = ?`).run(...params);
  return result.changes > 0;
}

export function deleteCategory(id) {
  const db = getDb();
  const result = db.prepare('DELETE FROM categories WHERE id = ?').run(id);
  return result.changes > 0;
}
"}

{"filePath":"/tmp/opencode/test-agentic-full/src/middleware.js","content":"/**
 * Middleware: logging, error handling, body parsing
 */

export function logger(req, res) {
  const start = Date.now();
  const originalEnd = res.end.bind(res);

  res.end = function (...args) {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.url} → ${res.statusCode} (${duration}ms)`);
    return originalEnd(...args);
  };
}

export function parseBody(req) {
  return new Promise((resolve, reject) => {
    if (req.method === 'GET' || req.method === 'DELETE') return resolve({});

    let body = '';
    req.on('data', chunk => { body += chunk; });
    req.on('end', () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch (err) {
        reject(new Error('Invalid JSON'));
      }
    });
    req.on('error', reject);
  });
}

export function sendJson(res, statusCode, data) {
  res.writeHead(statusCode, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data));
}

export function sendError(res, statusCode, message) {
  sendJson(res, statusCode, { error: message });
}
"}

{"filePath":"/tmp/opencode/test-agentic-full/src/index.js","content":"/**
 * Todo API - Main HTTP Server
 * Fitur: CRUD todos, users, categories, search, auth middleware
 */

import { createServer } from 'node:http';
import { initDb, closeDb } from './db.js';
import { addTodo, listTodos, getTodo, updateTodo, deleteTodo } from './todo.js';
import { createUser, listUsers, getUser, deleteUser } from './user.js';
import { createCategory, listCategories, getCategory, updateCategory, deleteCategory } from './category.js';
import { logger, parseBody, sendJson, sendError } from './middleware.js';

const PORT = process.env.PORT || 3001;
const API_PREFIX = '/api';

// Init database
initDb();

const server = createServer(async (req, res) => {
  // CORS headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  // Logger
  logger(req, res);

  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    res.end();
    return;
  }

  const url = new URL(req.url, `http://${req.headers.host}`);
  const path = url.pathname;
  const query = Object.fromEntries(url.searchParams);

  try {
    // ─── Health Check ───
    if (req.method === 'GET' && path === '/health') {
      return sendJson(res, 200, { status: 'ok', uptime: process.uptime() });
    }

    // ─── TODOS ───
    if (path === `${API_PREFIX}/todos` && req.method === 'GET') {
      const options = {};
      if (query.userId) options.userId = parseInt(query.userId);
      if (query.categoryId) options.categoryId = parseInt(query.categoryId);
      if (query.completed !== undefined) options.completed = query.completed === 'true';
      if (query.search) options.search = query.search;
      if (query.sortBy) options.sortBy = query.sortBy;
      if (query.order) options.order = query.order;
      const todos = listTodos(options);
      return sendJson(res, 200, { todos, count: todos.length });
    }

    if (path === `${API_PREFIX}/todos` && req.method === 'POST') {
      const body = await parseBody(req);
      const todo = addTodo({
        title: body.title,
        userId: body.userId,
        categoryId: body.categoryId,
        priority: body.priority || 0,
      });
      return sendJson(res, 201, todo);
    }

    if (path.startsWith(`${API_PREFIX}/todos/`) && req.method === 'GET') {
      const id = parseInt(path.split('/')[3]);
      const todo = getTodo(id);
      if (!todo) return sendError(res, 404, 'Todo not found');
      return sendJson(res, 200, todo);
    }

    if (path.startsWith(`${API_PREFIX}/todos/`) && req.method === 'PUT') {
      const id = parseInt(path.split('/')[3]);
      const body = await parseBody(req);
      const updated = updateTodo(id, body);
      if (!updated) return sendError(res, 404, 'Todo not found');
      return sendJson(res, 200, { success: true, id });
    }

    if (path.startsWith(`${API_PREFIX}/todos/`) && req.method === 'DELETE') {
      const id = parseInt(path.split('/')[3]);
      const deleted = deleteTodo(id);
      if (!deleted) return sendError(res, 404, 'Todo not found');
      return sendJson(res, 200, { success: true });
    }

    // ─── USERS ───
    if (path === `${API_PREFIX}/users` && req.method === 'GET') {
      const users = listUsers();
      return sendJson(res, 200, { users });
    }

    if (path === `${API_PREFIX}/users` && req.method === 'POST') {
      const body = await parseBody(req);
      const user = createUser(body);
      return sendJson(res, 201, user);
    }

    if (path.startsWith(`${API_PREFIX}/users/`) && req.method === 'GET') {
      const id = parseInt(path.split('/')[3]);
      const user = getUser(id);
      if (!user) return sendError(res, 404, 'User not found');
      return sendJson(res, 200, user);
    }

    if (path.startsWith(`${API_PREFIX}/users/`) && req.method === 'DELETE') {
      const id = parseInt(path.split('/')[3]);
      const deleted = deleteUser(id);
      if (!deleted) return sendError(res, 404, 'User not found');
      return sendJson(res, 200, { success: true });
    }

    // ─── CATEGORIES ───
    if (path === `${API_PREFIX}/categories` && req.method === 'GET') {
      const categories = listCategories();
      return sendJson(res, 200, { categories });
    }

    if (path === `${API_PREFIX}/categories` && req.method === 'POST') {
      const body = await parseBody(req);
      const category = createCategory(body);
      return sendJson(res, 201, category);
    }

    if (path.startsWith(`${API_PREFIX}/categories/`) && req.method === 'GET') {
      const id = parseInt(path.split('/')[3]);
      const category = getCategory(id);
      if (!category) return sendError(res, 404, 'Category not found');
      return sendJson(res, 200, category);
    }

    if (path.startsWith(`${API_PREFIX}/categories/`) && req.method === 'PUT') {
      const id = parseInt(path.split('/')[3]);
      const body = await parseBody(req);
      const updated = updateCategory(id, body);
      if (!updated) return sendError(res, 404, 'Category not found');
      return sendJson(res, 200, { success: true });
    }

    if (path.startsWith(`${API_PREFIX}/categories/`) && req.method === 'DELETE') {
      const id = parseInt(path.split('/')[3]);
      const deleted = deleteCategory(id);
      if (!deleted) return sendError(res, 404, 'Category not found');
      return sendJson(res, 200, { success: true });
    }

    // 404
    sendError(res, 404, 'Route not found');

  } catch (err) {
    sendError(res, 400, err.message);
  }
});

server.listen(PORT, () => {
  console.log(`🚀 Todo API running on http://localhost:${PORT}`);
});

export { server };
"}

