{"filePath":"/tmp/opencode/test-agentic-full/src/db.js","content":"/**
 * Database connection manager
 * Singleton pattern untuk better-sqlite3
 * Support reset untuk testing isolation
 */

import Database from 'better-sqlite3';

let db = null;

export function getDb(dbPath = ':memory:') {
  if (db) return db;
  db = new Database(dbPath);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  return db;
}

export function initDb(dbPath) {
  if (db) {
    try { db.close(); } catch (e) { /* ignore */ }
  }
  db = new Database(dbPath || ':memory:');
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');

  db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      email TEXT UNIQUE NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);

  db.exec(`
    CREATE TABLE IF NOT EXISTS categories (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT UNIQUE NOT NULL,
      description TEXT DEFAULT '',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);

  db.exec(`
    CREATE TABLE IF NOT EXISTS todos (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      completed INTEGER DEFAULT 0,
      user_id INTEGER REFERENCES users(id),
      category_id INTEGER REFERENCES categories(id),
      priority INTEGER DEFAULT 0,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);

  return db;
}

export function resetDb() {
  if (db) {
    db.exec('DELETE FROM todos');
    db.exec('DELETE FROM users');
    db.exec('DELETE FROM categories');
  }
}

export function closeDb() {
  if (db) {
    try { db.close(); } catch (e) { /* ignore */ }
    db = null;
  }
}

export function getStore() {
  return db ? 'sqlite' : 'none';
}
"}

