{"filePath":"/tmp/opencode/test-agentic-full/src/auth.js","content":"/**
 * Simple API Key authentication middleware
 */

const API_KEYS = new Set([
  'test-key-123',
  'admin-key-456',
]);

export function validateApiKey(req) {
  const authHeader = req.headers['authorization'];
  if (!authHeader) return false;
  const key = authHeader.replace('Bearer ', '').trim();
  return API_KEYS.has(key);
}

export function requireAuth(req, res) {
  if (!validateApiKey(req)) {
    res.writeHead(401, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Unauthorized - valid API key required' }));
    return false;
  }
  return true;
}

export function addApiKey(key) {
  if (key && key.length >= 8) {
    API_KEYS.add(key);
    return true;
  }
  return false;
}

export function removeApiKey(key) {
  return API_KEYS.delete(key);
}
"}

