      return this.fallbackResponse(req, 'client')
    }

    // Chat mode: jika AGENTIC_ALLOW_CHAT_LLM=0, skip dengan fallback (behavior lama).
    // Jika tidak di-set atau =1, coba session.prompt() dengan timeout lebih pendek.
