      const client = this.opencodeClient as {
        session: {
          prompt: (opts: {
            body: {
              system?: string
              noReply?: boolean
              model?: { providerID: string; modelID: string }
              parts: Array<{ type: string; text: string }>
            }
            path: { id: string }
          }) => Promise<{ data?: { parts?: Array<{ type: string; text?: string }> }; parts?: Array<{ type: string; text?: string }> }>
        }
      }

