   * LLM CALL PATH — 3 tier:
   *
   * 1. DIRECT API (chat mode): kalo env AGENTIC_DIRECT_API_KEY di-set,
   *    call OpenAI-compatible API langsung. No session.prompt().
   * 2. OpenCode SDK (normal): via client.session.prompt()
   * 3. Fallback: [NO_LLM] kalo semua gagal
   *
   * Chat mode: session.prompt() dengan noReply punya behavior berbeda.
   * Direct API lebih reliable untuk chat mode.
   */
  private async callOpenCode(req: LLMRequest): Promise<LLMResponse> {
    // ── Tier 1: Direct API (chat mode / sub-agent) ──
    const directApiKey = process.env.AGENTIC_DIRECT_API_KEY || process.env.OPENAI_API_KEY
    const directEndpoint = process.env.AGENTIC_DIRECT_ENDPOINT || 'https://api.openai.com/v1/chat/completions'
    const directModel = process.env.AGENTIC_DIRECT_MODEL || 'gpt-4o'

    if (this._chatMode && directApiKey) {
      try {
        return await this.callDirectAPI(req, directApiKey, directEndpoint, directModel)
      } catch (err) {
        logParseError('callDirectAPI', err);
        return this.fallbackResponse(req, 'error')
      }
    }

    // ── Tier 2: OpenCode SDK session.prompt() ──
    if (!this.opencodeClient || !this.pluginSessionId) {
      // Fallback ke direct API kalo SDK gak available (sub-agent tanpa chat mode)
      if (directApiKey) {
        try {
          return await this.callDirectAPI(req, directApiKey, directEndpoint, directModel)
        } catch (err) {
          logParseError('callDirectAPI (fallback)', err);
        }
      }
      return this.fallbackResponse(req, 'client')
    }

    try {
      const client = this.opencodeClient as {
        session: {
          prompt: (opts: {
            body: {
              system?: string
              noReply?: boolean
              model?: { providerID: string; modelID: string }
              parts: Array<{ type: string; text: string }>
            }
            path: { id: string }
          }) => Promise<{ data?: { parts?: Array<{ type: string; text?: string }> }; parts?: Array<{ type: string; text?: string }> }>
        }
      }

      const sdkModel = req.model ?? this.parseModelForSDK()

      const timeoutMs = 120_000
      const controller = new AbortController()
      const timeoutId = setTimeout(() => controller.abort(), timeoutMs)

      const result = await Promise.race([
        client.session.prompt({
          body: {
            system: req.jsonMode
              ? `${req.systemPrompt}\n\nRespond with ONLY valid JSON. No markdown, no explanation.`
              : req.systemPrompt,
            noReply: true,
            ...(sdkModel ? { model: sdkModel } : {}),
            parts: [{ type: "text", text: req.userPrompt }],
          },
          path: { id: this.pluginSessionId },
        }),
        new Promise<never>((_, reject) => {
          controller.signal.addEventListener("abort", () => {
            reject(new Error(`OpenCode call timed out after ${timeoutMs}ms`))
          })
        }),
      ])
      clearTimeout(timeoutId)

      const parts = result.data?.parts ?? result.parts ?? []
      const textPart = parts.find((p: { type: string; text?: string }) => p.type === "text")
      const text = textPart?.text ?? ""

      if (text.trim()) {
        return { content: text.trim(), finishReason: "stop" }
      }
    } catch (error) {
      logParseError('callOpenCode', error);
      // Fallback: coba direct API kalo session.prompt() gagal
      if (directApiKey) {
        try {
          return await this.callDirectAPI(req, directApiKey, directEndpoint, directModel)
        } catch (err) {
          logParseError('callDirectAPI (fallback after error)', err);
        }
      }
    }

    return this.fallbackResponse(req, 'error')
  }

  /**
   * Direct OpenAI-compatible API call.
   * Fallback ketika session.prompt() tidak available (chat mode / sub-agent).
   */
  private async callDirectAPI(req: LLMRequest, apiKey: string, endpoint: string, model: string): Promise<LLMResponse> {
    const messages: Array<{ role: string; content: string }> = []
    if (req.systemPrompt) {
      messages.push({ role: "system", content: req.systemPrompt })
    }
    messages.push({ role: "user", content: req.userPrompt })

    const body = JSON.stringify({
      model,
      messages,
      max_tokens: req.maxTokens ?? 4096,
      temperature: req.temperature ?? 0.3,
      ...(req.jsonMode ? { response_format: { type: "json_object" } } : {}),
    })

    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), 60_000)

    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${apiKey}`,
        },
        body,
        signal: controller.signal,
      })
      clearTimeout(timeoutId)

      if (!response.ok) {
        const errText = await response.text().catch(() => 'unknown error')
        throw new Error(`Direct API ${response.status}: ${errText}`)
      }

      const data = await response.json() as {
        choices?: Array<{ message?: { content?: string }; finish_reason?: string }>
        usage?: { prompt_tokens?: number; completion_tokens?: number }
      }

      const choice = data.choices?.[0]
      const content = choice?.message?.content ?? ''
      const finishReason = choice?.finish_reason ?? 'stop'

      return {
        content: content.trim(),
        finishReason,
        usage: data.usage ? {
          promptTokens: data.usage.prompt_tokens ?? 0,
          completionTokens: data.usage.completion_tokens ?? 0,
        } : undefined,
      }
    } catch (err) {
      clearTimeout(timeoutId)
      throw err
    }
  }"}

