  private async callDirectAPI(req: LLMRequest, apiKey: string): Promise<LLMResponse> {
    const endpoint = process.env.AGENTIC_DIRECT_ENDPOINT || 'https://api.openai.com/v1/chat/completions'
    const model = process.env.AGENTIC_DIRECT_MODEL || 'gpt-4o'

    const messages: Array<{ role: string; content: string }> = []
    if (req.systemPrompt) messages.push({ role: "system", content: req.systemPrompt })
    messages.push({ role: "user", content: req.userPrompt })

