          client.session.prompt({
            body: {
              system: req.jsonMode
                ? `${req.systemPrompt}\n\nRespond with ONLY valid JSON. No markdown, no explanation.`
                : req.systemPrompt,
              noReply: this._suppressOutput,
              ...(sdkModel ? { model: sdkModel } : {}),
              parts: [{ type: "text", text: req.userPrompt }],
            },
            path: { id: this.pluginSessionId },
          }),
          new Promise<never>((_, reject) => {
            controller.signal.addEventListener("abort", () => {
              reject(new Error(`OpenCode call timed out after ${timeoutMs}ms`))
            })
          }),
        ])
        clearTimeout(timeoutId)

        // Coba extract dari parts, content, message, choices
        const extractResponse = (data: any): string => {
          if (!data) return ''
          for (const p of data.parts ?? data.data?.parts ?? []) {
            if (p.text?.trim()) return p.text.trim()
          }
          if (data.content) return data.content
          if (data.message?.content) return data.message.content
          if (data.choices?.[0]?.message?.content) return data.choices[0].message.content
          return ''
        }

        const text = extractResponse(result)
        if (text) return { content: text, finishReason: "stop" }
      } catch (error) {
        logParseError('callOpenCode', error);
      }
    }

    return this.fallbackResponse(req, 'error')
  }"}

